def env_bool(value, default=False):
    if value is None:
        return default
    text = str(value).strip().lower()
    if text in _TRUE_STRINGS:
        return True
    if text in _FALSE_STRINGS:
        return False
    return default

def load(env):
    return {'debug': env_bool(env.get('APP_DEBUG'), False)}
